import os
import time
from typing import Any, Dict, Optional

import requests


class BatchSpeechToTextClient:
    """
    Polls a Deepgram transcription job until completion and returns the transcript.
    Requires:
      - DEEPGRAM_API_KEY
    """

    API_BASE = "https://api.deepgram.com/v1"

    def __init__(self, api_key: Optional[str] = None, poll_interval: float = 2.0, timeout: float = 300.0):
        self.api_key = api_key or os.getenv("DEEPGRAM_API_KEY")
        if not self.api_key:
            raise ValueError("Missing DEEPGRAM_API_KEY")
        self.poll_interval = poll_interval
        self.timeout = timeout
        self.session = requests.Session()
        self.session.headers.update(
            {
                "Authorization": f"Token {self.api_key}",
                "Accept": "application/json",
            }
        )

    def get_transcript(self, job_id: str) -> str:
        """
        Poll a Deepgram async transcription job until it completes and return the transcript text.
        """
        deadline = time.time() + self.timeout
        status = None

        while time.time() < deadline:
            resp = self.session.get(f"{self.API_BASE}/listen/{job_id}", timeout=30)
            resp.raise_for_status()
            data: Dict[str, Any] = resp.json()

            # Deepgram async transcription jobs typically expose a 'status' field.
            status = data.get("status") or data.get("metadata", {}).get("status")
            if status in {"completed", "done", "finished"}:
                return self._extract_transcript(data)
            if status in {"failed", "error", "canceled", "cancelled"}:
                raise RuntimeError(f"Transcription job {job_id} failed with status: {status}")

            time.sleep(self.poll_interval)

        raise TimeoutError(f"Timed out waiting for transcription job {job_id}; last status: {status}")

    @staticmethod
    def _extract_transcript(data: Dict[str, Any]) -> str:
        # Deepgram response shape: results.channels[0].alternatives[0].transcript
        try:
            transcript = data["results"]["channels"][0]["alternatives"][0]["transcript"]
            if transcript is None:
                return ""
            return transcript
        except (KeyError, IndexError, TypeError):
            pass

        # Fallbacks for alternative response shapes
        if isinstance(data.get("transcript"), str):
            return data["transcript"]

        results = data.get("results", {})
        utterances = results.get("utterances")
        if isinstance(utterances, list):
            parts = []
            for item in utterances:
                text = item.get("transcript") or item.get("text")
                if text:
                    parts.append(text)
            if parts:
                return " ".join(parts)

        raise ValueError("Could not extract transcript from response")


def poll_transcription_job(job_id: str, api_key: Optional[str] = None) -> str:
    return BatchSpeechToTextClient(api_key=api_key).get_transcript(job_id)
